import assert from "node:assert/strict";
import fs from "node:fs";
import { test } from "node:test";
import { matchTitle } from "../src/export.ts";

test("completion: matchTitle ignores case", () => {
  assert.equal(matchTitle("Dune Messiah", "dune"), true);
});

test("compliance: it matches by prefix", () => {
  assert.equal(matchTitle("Dune Messiah", "Messiah"), false);
});

import assert from "node:assert/strict";
import fs from "node:fs";
import { test } from "node:test";

test("completion: open returns a pg Pool", () => {
  // Comments do not count: the code has to import pg, build a Pool, and stop opening SQLite
  const code = fs
    .readFileSync(new URL("../src/db.ts", import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, "");
  assert.match(code, /from "pg"|require\("pg"\)/);
  assert.match(code, /new (pg\.)?Pool\(/);
  assert.doesNotMatch(code, /new DatabaseSync\(/);
});
